'use strict';
const vscode = require('vscode');
const fs = require('fs');
const path = require('path');
const { execFile } = require('child_process');
const { LanguageClient, TransportKind } = require('vscode-languageclient/node');

let client;
let output;

const exeName = (name) => (process.platform === 'win32' ? name + '.exe' : name);
const settings = () => vscode.workspace.getConfiguration('blitz');

/** A program of the installation: the setting for the program, then bin/ of the installation folder, then PATH. */
function findProgram(setting, name) {
  const configured = settings().get(setting, '');
  if (configured) return configured;
  const installed = settings().get('installPath', '');
  if (installed) {
    const candidate = path.join(installed, 'bin', exeName(name));
    if (fs.existsSync(candidate)) return candidate;
  }
  const bundled = path.join(__dirname, '..', 'bin', exeName(name));
  if (fs.existsSync(bundled)) return bundled;
  return name; // PATH
}

function startServer(context) {
  const command = findProgram('server.path', 'blitz-lsp');
  const env = Object.assign({}, process.env);
  const userlibs = settings().get('userlibsDirectory', '');
  if (userlibs) env.BLITZLLVM_USERLIBS = userlibs;
  client = new LanguageClient('blitz', 'BlitzLLVM', { command, args: ['--stdio'], transport: TransportKind.stdio, options: { env } }, {
    documentSelector: [{ scheme: 'file', language: 'blitzbasic' }],
    initializationOptions: { warningLevel: settings().get('warningLevel', 2) },
    synchronize: { configurationSection: 'blitz' },
    outputChannel: output
  });
  client.start().catch((error) => {
    vscode.window.showErrorMessage(`The BlitzLLVM language server (${command}) did not start: ${error.message}. Set "blitz.installPath" or "blitz.server.path".`);
  });
  context.subscriptions.push({ dispose: () => client && client.stop() });
}

async function restartServer(context) {
  if (client) {
    try { await client.stop(); } catch (e) { /* it was not running */ }
    client = undefined;
  }
  startServer(context);
}

////////////////////////////////////////////////////////////////////////////////
// Building, running
////////////////////////////////////////////////////////////////////////////////
function activeProgram(file) {
  if (file) return file;
  const editor = vscode.window.activeTextEditor;
  if (!editor || editor.document.languageId !== 'blitzbasic' || editor.document.uri.scheme !== 'file') {
    vscode.window.showErrorMessage('Open a Blitz program (.bb) first.');
    return undefined;
  }
  return editor.document.uri.fsPath;
}

function outputPath(file, mode) {
  const folder = vscode.workspace.getWorkspaceFolder(vscode.Uri.file(file));
  const base = folder ? folder.uri.fsPath : path.dirname(file);
  const name = path.basename(file, path.extname(file));
  return path.join(base, settings().get('build.outputDirectory', 'build/blitz'), mode, process.platform === 'win32' ? name + '.exe' : name);
}

/** The arguments of blitzcc for an action. Debug is -d (no optimisation, exact math) with debug information (-g). */
function compilerArguments(action, mode, file, extra) {
  const args = settings().get('compiler.arguments', []).slice();
  if (mode === 'debug') args.push('-d', '-g');
  if (action === 'check') args.push('-c');
  if (action === 'build') args.push('-o', outputPath(file, mode));
  args.push(file);
  if (action === 'run' && extra && extra.length) args.push('--args', ...extra);
  return args;
}

function makeTask(action, mode, file, folder) {
  const definition = { type: 'blitz', action, mode, file };
  const title = { build: 'Build', run: 'Run', check: 'Check' }[action] + (action === 'check' ? '' : ` (${mode})`);
  const execution = new vscode.ProcessExecution(findProgram('compiler.path', 'blitzcc'), compilerArguments(action, mode, file), { cwd: path.dirname(file) });
  const task = new vscode.Task(definition, folder || vscode.TaskScope.Workspace, `${title}: ${path.basename(file)}`, 'blitz', execution, '$blitzcc');
  if (action === 'build') task.group = mode === 'release' ? vscode.TaskGroup.Build : undefined;
  task.presentationOptions = { reveal: vscode.TaskRevealKind.Always, panel: vscode.TaskPanelKind.Dedicated, clear: true };
  return task;
}

class BlitzTaskProvider {
  provideTasks() {
    const editor = vscode.window.activeTextEditor;
    if (!editor || editor.document.languageId !== 'blitzbasic' || editor.document.uri.scheme !== 'file') return [];
    const file = editor.document.uri.fsPath;
    return [
      makeTask('build', 'debug', file), makeTask('build', 'release', file),
      makeTask('run', 'debug', file), makeTask('run', 'release', file), makeTask('check', 'debug', file)
    ];
  }
  resolveTask(task) {
    const d = task.definition;
    const file = d.file || activeProgram();
    return file ? makeTask(d.action, d.mode, file, task.scope) : undefined;
  }
}

function runTask(action, mode) {
  return () => {
    const file = activeProgram();
    if (!file) return;
    vscode.workspace.saveAll(false).then(() => vscode.tasks.executeTask(makeTask(action, mode, file)));
  };
}

////////////////////////////////////////////////////////////////////////////////
// Debugging: the program is built with debug information and handed to a native debugger.
////////////////////////////////////////////////////////////////////////////////
function build(file, mode) {
  return new Promise((resolve, reject) => {
    const exe = outputPath(file, mode);
    fs.mkdirSync(path.dirname(exe), { recursive: true });
    const compiler = findProgram('compiler.path', 'blitzcc');
    const args = compilerArguments('build', mode, file);
    output.appendLine(`> ${compiler} ${args.join(' ')}`);
    execFile(compiler, args, { cwd: path.dirname(file), maxBuffer: 64 * 1024 * 1024 }, (error, stdout, stderr) => {
      output.append(stdout || '');
      output.append(stderr || '');
      if (error) { output.show(true); reject(new Error(`blitzcc failed (${error.code || error.message}), see the output "BlitzLLVM".`)); } else { resolve(exe); }
    });
  });
}

function pickAdapter() {
  const chosen = settings().get('debug.adapter', 'auto');
  if (chosen !== 'auto') return chosen;
  if (process.platform === 'win32') return 'cppvsdbg';
  if (vscode.extensions.getExtension('vadimcn.vscode-lldb')) return 'lldb';
  return 'cppdbg';
}

class BlitzDebugConfigurationProvider {
  async resolveDebugConfiguration(folder, config) {
    if (!config.type) { // F5 without a launch.json
      config.type = 'blitz';
      config.request = 'launch';
      config.name = 'Debug the open program';
      config.program = '${file}';
    }
    let file = config.program;
    if (!file || file === '${file}') file = activeProgram();
    if (!file) return undefined;
    await vscode.workspace.saveAll(false);
    let exe;
    try {
      exe = await vscode.window.withProgress({ location: vscode.ProgressLocation.Notification, title: 'Building with debug information' }, () => build(file, 'debug'));
    } catch (error) {
      vscode.window.showErrorMessage(error.message);
      return undefined;
    }
    const adapter = pickAdapter();
    const cwd = config.cwd || path.dirname(file);
    const native = { name: config.name, request: 'launch', type: adapter, program: exe, args: config.args || [], cwd };
    if (adapter === 'cppdbg') {
      native.MIMode = process.platform === 'darwin' ? 'lldb' : 'gdb';
      native.stopAtEntry = !!config.stopAtEntry;
      native.externalConsole = false;
    } else if (adapter === 'cppvsdbg') {
      native.stopAtEntry = !!config.stopAtEntry;
      native.console = 'integratedTerminal';
    } else {
      native.stopOnEntry = !!config.stopAtEntry;
    }
    vscode.debug.startDebugging(folder, native);
    return undefined; // The native debugger was started instead
  }
}

////////////////////////////////////////////////////////////////////////////////
function activate(context) {
  output = vscode.window.createOutputChannel('BlitzLLVM');
  context.subscriptions.push(output);
  startServer(context);

  context.subscriptions.push(
    vscode.commands.registerCommand('blitz.run.debug', runTask('run', 'debug')),
    vscode.commands.registerCommand('blitz.run.release', runTask('run', 'release')),
    vscode.commands.registerCommand('blitz.build.debug', runTask('build', 'debug')),
    vscode.commands.registerCommand('blitz.build.release', runTask('build', 'release')),
    vscode.commands.registerCommand('blitz.check', runTask('check', 'debug')),
    vscode.commands.registerCommand('blitz.tidy', () => vscode.commands.executeCommand('editor.action.codeAction', { kind: 'source.fixAll.blitz', apply: 'first' })),
    vscode.commands.registerCommand('blitz.restartServer', () => restartServer(context)),
    vscode.tasks.registerTaskProvider('blitz', new BlitzTaskProvider()),
    vscode.debug.registerDebugConfigurationProvider('blitz', new BlitzDebugConfigurationProvider()),
    vscode.workspace.onDidChangeConfiguration((event) => {
      if (event.affectsConfiguration('blitz.installPath') || event.affectsConfiguration('blitz.server.path') || event.affectsConfiguration('blitz.userlibsDirectory')) {
        restartServer(context);
      }
    })
  );
}

function deactivate() {
  return client ? client.stop() : undefined;
}

module.exports = { activate, deactivate };
